    var name = mr.GetString(td.Name);
    if (name.Contains("CollectionBehavior") || name.Contains("TestCaseOrderer")) {
        var ns = mr.GetString(td.Namespace);
        Console.WriteLine($"\nType: {ns}.{name}");
        foreach (var mh in td.GetMethods()) {
            var method = mr.GetMethodDefinition(mh);
            var mname = mr.GetString(method.Name);
            if (mname == ".ctor") {
                var sig = method.DecodeSignature(new SignatureTypeProvider(), null);
                var parms = string.Join(", ", sig.ParameterTypes);
                Console.WriteLine($"  ctor({parms})");
            }
        }
        foreach (var ph in td.GetProperties()) {
            var prop = mr.GetPropertyDefinition(ph);
            var pname = mr.GetString(prop.Name);
            Console.WriteLine($"  prop: {pname}");
        }
    }
}

class SignatureTypeProvider : ISignatureTypeProvider<string, object?> {
    public string GetPrimitiveType(PrimitiveTypeCode c) => c.ToString();
    public string GetTypeFromDefinition(MetadataReader r, TypeDefinitionHandle h, byte v) { var td = r.GetTypeDefinition(h); return r.GetString(td.Name); }
    public string GetTypeFromReference(MetadataReader r, TypeReferenceHandle h, byte v) { var tr = r.GetTypeReference(h); return r.GetString(tr.Name); }
    public string GetTypeFromSpecification(MetadataReader r, object? g, TypeSpecificationHandle h, byte v) => "spec";
    public string GetSZArrayType(string e) => e + "[]";
    public string GetGenericInstantiation(string g, System.Collections.Immutable.ImmutableArray<string> a) => g + "<" + string.Join(",",a) + ">";
    public string GetArrayType(string e, ArrayShape s) => e + "[]";
    public string GetByReferenceType(string e) => "ref " + e;
    public string GetPointerType(string e) => e + "*";
    public string GetFunctionPointerType(MethodSignature<string> s) => "fnptr";
    public string GetGenericMethodParameter(object? g, int i) => "!!" + i;
    public string GetGenericTypeParameter(object? g, int i) => "!" + i;
    public string GetModifiedType(string m, string u, bool r) => u;
    public string GetPinnedType(string e) => e;
}
